using Microsoft.Data.SqlClient;
using BellasBoutique.Web.Models.Demo;
using BellasBoutique.Web.Services;
namespace BellasBoutique.Web.Data;
public partial class TiendaDb {
 public void Ejecutar(string sql,params (string,object?)[] p){using var c=Abrir();using var q=Cmd(c,sql,p);q.ExecuteNonQuery();}
 public List<T> Leer<T>(string sql,Func<SqlDataReader,T> map,params (string,object?)[] p){using var c=Abrir();using var q=Cmd(c,sql,p);using var r=q.ExecuteReader();var l=new List<T>();while(r.Read())l.Add(map(r));return l;}
 public void MigrarClaves(){foreach(var u in Usuarios().Where(u=>!u.Contrasena.StartsWith("v1:")))Ejecutar("UPDATE Usuarios SET Contrasena=@p WHERE Id=@id",("@p",CifradoService.Hash(u.Contrasena)),("@id",u.Id));}
 public void Intento(string s,bool ok)=>Ejecutar("INSERT IntentosLogin(Identificador,Exitoso) VALUES(@s,@ok)",("@s",s.Length>150?s[..150]:s),("@ok",ok));
 public void Clave(int id,string clave)=>Ejecutar("UPDATE Usuarios SET Contrasena=@p WHERE Id=@id",("@p",CifradoService.Hash(clave)),("@id",id));
 public void Log(int id,string accion,string detalle)=>Ejecutar("INSERT Bitacora(UsuarioId,Usuario,Rol,Accion,Detalle) SELECT Id,Nombre+' '+Apellidos,Rol,@a,@d FROM Usuarios WHERE Id=@id",("@id",id),("@a",accion),("@d",detalle));
 public List<BitacoraFila> Bitacora()=>Leer("SELECT * FROM Bitacora ORDER BY Id DESC",r=>new BitacoraFila((DateTime)r["Fecha"],(string)r["Usuario"],(string)r["Rol"],(string)r["Accion"],(string)r["Detalle"]));
 public List<VentaFila> Ventas()=>Leer("SELECT * FROM Ventas ORDER BY Id DESC",r=>new VentaFila((DateTime)r["Fecha"],$"F-{(int)r["FacturaId"]:0000}",(string)r["Producto"],(string)r["Categoria"],(int)r["Cantidad"],(decimal)r["Precio"]));
 public List<PagoFila> Pagos()=>Leer("SELECT p.Id,p.Metodo,p.Estado,p.Monto,u.Nombre+' '+u.Apellidos Cliente,f.Id FacturaId FROM Pagos p JOIN Carritos c ON c.Id=p.CarritoId JOIN Usuarios u ON u.Id=c.UsuarioId LEFT JOIN Facturas f ON f.PagoId=p.Id ORDER BY p.Id DESC",r=>new PagoFila(r["FacturaId"] is int n?$"F-{n:0000}":"—",(string)r["Cliente"],(string)r["Metodo"],(decimal)r["Monto"],(string)r["Estado"]));
 public List<ItemDemo> Carrito(int uid)=>Leer("SELECT p.*,d.Cantidad FROM Carritos c JOIN DetallesCarrito d ON d.CarritoId=c.Id JOIN Productos p ON p.Id=d.ProductoId WHERE c.UsuarioId=@u AND c.Cerrado=0",r=>new ItemDemo{ProductoId=(int)r["Id"],Nombre=(string)r["Nombre"],Categoria=(string)r["Categoria"],Precio=(decimal)r["Precio"],Cantidad=(int)r["Cantidad"],Imagen=(string)r["Imagen"]},("@u",uid));
 public void GuardarCarrito(int uid,List<ItemDemo> items){using var c=Abrir();using var tx=c.BeginTransaction(System.Data.IsolationLevel.Serializable);SqlCommand Q(string s,params (string,object?)[] p){var q=Cmd(c,s,p);q.Transaction=tx;return q;}using var get=Q("SELECT Id FROM Carritos WITH (UPDLOCK,HOLDLOCK) WHERE UsuarioId=@u AND Cerrado=0",("@u",uid));var found=get.ExecuteScalar();int id;if(found==null){using var add=Q("INSERT Carritos(UsuarioId) OUTPUT INSERTED.Id VALUES(@u)",("@u",uid));id=(int)add.ExecuteScalar()!;}else id=(int)found;using(var del=Q("DELETE DetallesCarrito WHERE CarritoId=@i",("@i",id)))del.ExecuteNonQuery();foreach(var i in items){using var add=Q("INSERT DetallesCarrito VALUES(@i,@p,@n)",("@i",id),("@p",i.ProductoId),("@n",i.Cantidad));add.ExecuteNonQuery();}tx.Commit();}
 public int Comprar(UsuarioDemo u,string metodo,string direccion,string estado){using var c=Abrir();using var tx=c.BeginTransaction(System.Data.IsolationLevel.Serializable);SqlCommand Q(string s,params (string,object?)[] p){var q=Cmd(c,s,p);q.Transaction=tx;return q;}object? Scalar(string s,params (string,object?)[] p){using var q=Q(s,p);return q.ExecuteScalar();}void Exec(string s,params (string,object?)[] p){using var q=Q(s,p);q.ExecuteNonQuery();}
 var obj=Scalar("SELECT Id FROM Carritos WITH(UPDLOCK,HOLDLOCK) WHERE UsuarioId=@u AND Cerrado=0",("@u",u.Id));if(obj==null)throw new InvalidOperationException("Carrito vacío.");int cart=(int)obj;var items=new List<ItemDemo>();using(var q=Q("SELECT p.*,d.Cantidad FROM DetallesCarrito d JOIN Productos p WITH(UPDLOCK,HOLDLOCK) ON p.Id=d.ProductoId WHERE d.CarritoId=@c",("@c",cart)))using(var r=q.ExecuteReader()){while(r.Read()){if(!(bool)r["Activo"]||(int)r["Stock"]<(int)r["Cantidad"])throw new InvalidOperationException("Stock insuficiente.");items.Add(new(){ProductoId=(int)r["Id"],Nombre=(string)r["Nombre"],Categoria=(string)r["Categoria"],Precio=(decimal)r["Precio"],Cantidad=(int)r["Cantidad"]});}}if(items.Count==0)throw new InvalidOperationException("Carrito vacío.");var sub=items.Sum(i=>i.Precio*i.Cantidad);var iva=Math.Round(sub*.13m,2,MidpointRounding.AwayFromZero);Exec("UPDATE Pagos SET Estado='Fallido' WHERE CarritoId=@c AND Estado='Pendiente'",("@c",cart));int pago=(int)Scalar("INSERT Pagos(CarritoId,Metodo,Estado,Monto) OUTPUT INSERTED.Id VALUES(@c,@m,@e,@t)",("@c",cart),("@m",metodo),("@e",estado),("@t",sub+iva))!;if(estado!="Exitoso"){tx.Commit();return 0;}
 int f=(int)Scalar("INSERT Facturas(UsuarioId,CarritoId,PagoId,Cliente,Correo,Direccion,Subtotal,Impuesto,Total) OUTPUT INSERTED.Id VALUES(@u,@c,@p,@n,@e,@d,@s,@i,@t)",("@u",u.Id),("@c",cart),("@p",pago),("@n",u.NombreCompleto),("@e",u.Correo),("@d",direccion),("@s",sub),("@i",iva),("@t",sub+iva))!;
 foreach(var i in items){Exec("UPDATE Productos SET Stock=Stock-@n WHERE Id=@p",("@n",i.Cantidad),("@p",i.ProductoId));Exec("INSERT DetallesFactura(FacturaId,ProductoId,Nombre,Categoria,Cantidad,Precio) VALUES(@f,@p,@nombre,@cat,@n,@precio); INSERT Ventas(FacturaId,ProductoId,Producto,Categoria,Cantidad,Precio) VALUES(@f,@p,@nombre,@cat,@n,@precio)",("@f",f),("@p",i.ProductoId),("@nombre",i.Nombre),("@cat",i.Categoria),("@n",i.Cantidad),("@precio",i.Precio));}Exec("UPDATE Carritos SET Cerrado=1 WHERE Id=@c; INSERT Bitacora(UsuarioId,Usuario,Rol,Accion,Detalle) VALUES(@u,@nombre,@rol,'Compra',@detalle)",("@c",cart),("@u",u.Id),("@nombre",u.NombreCompleto),("@rol",u.Rol),("@detalle",$"Factura F-{f:0000}"));tx.Commit();return f;}
 public FacturaDemo? Factura(int uid,int? id=null){var f=Leer("SELECT TOP 1 f.*,p.Metodo FROM Facturas f JOIN Pagos p ON p.Id=f.PagoId WHERE f.UsuarioId=@u AND (@i=0 OR f.Id=@i) ORDER BY f.Id DESC",r=>new FacturaDemo{Numero=(int)r["Id"],Cliente=(string)r["Cliente"],Correo=(string)r["Correo"],Direccion=(string)r["Direccion"],Metodo=(string)r["Metodo"],Fecha=(DateTime)r["Fecha"]},("@u",uid),("@i",id??0)).FirstOrDefault();if(f!=null)f.Detalle=Leer("SELECT * FROM DetallesFactura WHERE FacturaId=@f",r=>new ItemDemo{ProductoId=(int)r["ProductoId"],Nombre=(string)r["Nombre"],Categoria=(string)r["Categoria"],Cantidad=(int)r["Cantidad"],Precio=(decimal)r["Precio"]},("@f",f.Numero));return f;}
 public List<ChatFila> Chat(int cliente)=>Leer("SELECT * FROM MensajesChat WHERE ClienteId=@c ORDER BY Id",r=>new ChatFila((int)r["Id"],(int)r["EmisorId"],(string)r["Texto"],(DateTime)r["Fecha"]),("@c",cliente));
 public void Mensaje(int cliente,int emisor,string texto)=>Ejecutar("INSERT MensajesChat(ClienteId,EmisorId,Texto) VALUES(@c,@e,@t)",("@c",cliente),("@e",emisor),("@t",texto));
 public List<UsuarioDemo> Conversaciones()=>Usuarios().Where(u=>u.Rol=="Cliente").ToList();
 public List<FeedbackFila> Feedback()=>Leer("SELECT u.Nombre+' '+u.Apellidos Usuario,e.Comentario Texto,e.Fecha,e.Puntaje FROM Encuestas e JOIN Usuarios u ON u.Id=e.UsuarioId UNION ALL SELECT u.Nombre+' '+u.Apellidos,s.Texto,s.Fecha,NULL FROM Sugerencias s JOIN Usuarios u ON u.Id=s.UsuarioId ORDER BY Fecha DESC",r=>new FeedbackFila((string)r["Usuario"],r["Texto"] as string??"",(DateTime)r["Fecha"],r["Puntaje"] as int?));
}